29	const ONSALE_ID_COOLDOWN_MS = 6 * 60 * 60 * 1000;
30	const ONSALE_QTY_COOLDOWN_MS = 30 * 60 * 1000; // 同一店同 from→to 数量卡 30 分钟内不重复
31	const ONSALE_SCAN_DEBOUNCE_MS = 6000;
32	const ONSALE_QTY_CONFIRM_HITS = 2;            // 同一候选值连续命中次数
