// ─── mallId 归属（v19.3）───
function resolveByMall(map, mallId, dom) {
  const id = mallId != null && mallId !== '' ? String(mallId) : '';
  if (id && map[id]) {
    if (dom && dom !== map[id]) {
      const owned = Object.keys(map).find(function (k) {
        return map[k] === dom && k !== id;
      });
      if (!owned) {
        map[id] = dom;
        return dom;
      }
      return map[id];
    }
    return map[id];
  }
