    if (dom && dom !== map[id]) {
      const owned = Object.keys(map).find(function (k) {
        return map[k] === dom && k !== id;
      });
      if (!owned) {
        map[id] = dom;
        return dom;
      }
      return map[id];
    }
    return map[id];
  }
