    fresh = [];
  }
  if (fresh.length) nextAlerted = markAlerted(nextAlerted, fresh, now);
  nextAlerted = markAlerted(nextAlerted, pool, now);
  return {
    fresh: fresh,
    nextAlerted: nextAlerted,
    silenced: silenced,
    seeded: seeded,
    chipReallyUp: chipReallyUp,
    high: Math.max(prevHigh, curWatch || 0),
